import { build } from 'esbuild';
const load = async (f) => { const r = await build({entryPoints:[f],bundle:true,format:'esm',write:false,platform:'node'}); return import('data:text/javascript;base64,'+Buffer.from(r.outputFiles[0].text).toString('base64')); };
const a = await load('src/module.ts'), b = await load('out/module.ts');
const names=['lee','kim','park','choi','jung']; const R=(n,x)=>Math.floor(Math.random()*n)+x;
let bad=0;
for (let i=0;i<5000;i++){
 const rows=Array.from({length:R(13,0)},()=>({id:R(10,0),name:names[R(5,0)],age:R(43,18)}));
 const v=Array.from({length:R(21,0)},()=>R(26,-5)).sort((x,y)=>x-y);
 if (JSON.stringify(a.byId(rows))!==JSON.stringify(b.byId(rows))||a.totalAge(rows)!==b.totalAge(rows)||JSON.stringify(a.dedupeSorted(v))!==JSON.stringify(b.dedupeSorted(v))) bad++;
}
console.log('mismatches',bad);
EOF
